import subprocess


def scan_network(target):
    """Scan the network using nmap for educational purposes."""
    try:
        # Run nmap command
        result = subprocess.run(['nmap', '-sP', target], capture_output=True, text=True)
        return result.stdout
    except Exception as e:
        return str(e)

